from contextlib import nullcontext
from typing import Any

from sqlalchemy import inspect as sa_inspect
from sqlalchemy import text


class PostgresTenantExportRepository:
    """Read-only canonical tenant export data authority.

    Security / scope rules:
      * tenant scope is verified against principal -> hospital -> tenant;
      * table selection is an explicit whitelist;
      * AHOS28 / platform-internal tables are never readable here;
      * all SQL generated by this class is SELECT-only;
      * this repository does not create packages or write database state.
    """

